DEYDA_INTERNAL_1417346_ZLIB
# Optional core modules: unavailable support produces UNKNOWN, never installs.
sub internal_manifest {
    require MIME::Base64;
    require Compress::Zlib;
    my $packed=MIME::Base64::decode_base64($internal_compressed_b64);
    die "compressed baseline checksum mismatch" unless Digest::SHA::sha256_hex($packed) eq 'b63935d51bad5cfed41f12b1f3154907d5bc60c9d5cdf6b9b6072c1acb913e65';
    my $raw=Compress::Zlib::uncompress($packed);
    die "baseline decompression failed" unless defined($raw) && length($raw)==12522693;
    die "baseline checksum mismatch" unless Digest::SHA::sha256_hex($raw) eq '9d444ae3220af2d770aff82473e3bd37dc4f264b127c0cfe3334c7fe3c6f0ebf';
    return decode_json($raw);
}

my $ok=eval {
    if ($manifest_path) {open my $mf,'<',$manifest_path or die;local $/;my $raw=<$mf>;die if length($raw)>16*1024*1024;$manifest=decode_json($raw);}
    elsif ($build =~ /^14[.]1-73[.]46(?:[.]nc)?$/) {
        $manifest=internal_manifest();
        finding('CHECK','Using integrated operator-supplied 14.1-73.46 standard test-device reference (2026-10-13); not Citrix-published checksums. Customization, installed packages and generated caches may explain differences.');
    } else {finding('CHECK','UNKNOWN: no integrated file manifest for this exact build/edition; supply DEYDA_FILE_BASELINE.');exit;}
    die unless ref($manifest) eq 'HASH' && ($manifest->{schema}//'') eq 'deyda-files-v1' && $manifest->{approved} && ref($manifest->{roots}) eq 'ARRAY' && @{$manifest->{roots}} && ref($manifest->{files}) eq 'HASH';1;
};
# Give the file comparison its own bounded window after timestamp analysis.
alarm 60;
if (!$ok) {finding('CHECK','UNKNOWN: file manifest invalid/unreadable, compressed baseline integrity failed, or decompression modules unavailable.');exit;}
my ($familybuild)=$build =~ /((?:14|13)\.1-\d+\.\d+)/;
if (!$familybuild || ($manifest->{build}//'') ne $familybuild || $build =~ /FIPS|NDcPP/i) {finding('CHECK','UNKNOWN: file baseline build/edition does not match selected standard build.');exit;}
# Exact-build single-file references stay separate from tree inventory.
for my $path ('/bin/sh','/netscaler/ns_monuploadd_err.pl') {
    my $entry=$manifest->{single_file_references}{$path};
    next unless ref($entry) eq 'HASH' && ($entry->{sha256}//'') =~ /^[a-fA-F0-9]{64}$/;
    if (!-f $path || -l $path) {finding('CHECK',"Single-file reference unavailable or symlinked: $path");next;}
    if (defined($entry->{mode}) && $entry->{mode}=~/^[0-7]{3,4}$/) {
        my @st=lstat($path);
        if (@st) {
            my $actual=sprintf('%04o',$st[2]&07777);my $expected=sprintf('%04o',oct($entry->{mode}));
            finding($actual eq $expected?'OK':'CHECK',"$path internal permission reference: expected=$expected observed=$actual.");
        } else {finding('CHECK',"$path permission metadata unavailable.");}
    }
    my $hash=cached_digest($path,0);
    finding(defined($hash) && $hash eq lc($entry->{sha256})?'OK':'CHECK',"$path exact-build internal reference: ".(defined($hash) && $hash eq lc($entry->{sha256})?'hash matches':'differs or unavailable').'; not a vendor checksum or proof of compromise.');
}
my @roots=@{$manifest->{roots}};
my $baseline_digest=Digest::SHA::sha256_hex(JSON::PP->new->canonical->encode($manifest));
print "Coverage-Condition: baseline_sha256=$baseline_digest\n";
print "Coverage-Condition: baseline_source=".($manifest_path?'EXTERNAL':'INTERNAL')."\n";

for my $root (@roots) {
    if ($root !~ m{^/(?:netscaler(?:\.local)?|nsconfig|var/netscaler|var/python)(?:/[^\x00-\x1f]*)?$} || $root =~ m{(?:^|/)\.\.?(/|$)} || -l $root || !-d $root) {finding('CHECK','UNKNOWN: manifest root unsupported, missing or symlinked.');exit;}
}
my %links_seen;my ($link_count,$link_changed,$link_unknown,$link_missing)=(0,0,0,0);
my ($mode_checked,$mode_changed,$type_changed,$mode_unknown)=(0,0,0,0);
my %type_seen;
my %observed;my ($scanned,$partial,$new,$changed,$missing)=(0,0,0,0,0);
my ($variable_new,$variable_changed,$variable_missing)=(0,0,0);
sub variable_path {return $_[0] =~ m{(?:^|/)(?:__pycache__)(?:/|$)|[.]py[co]$} ? 1:0;}

my $inside=sub {my($f)=@_;return scalar grep {$f eq $_ || index($f,"$_/")==0} @roots;};
for my $f(keys %{$manifest->{files}}) {
    if (!$inside->($f) || $f =~ /[\x00-\x1f]/ || $f =~ m{(?:^|/)\.\.?(/|$)} || $manifest->{files}{$f} !~ /^[a-fA-F0-9]{64}$/) {finding('CHECK','UNKNOWN: manifest file path/hash invalid or outside declared roots.');exit;}
}
if (exists($manifest->{symlinks})) {
    if (ref($manifest->{symlinks}) ne 'HASH') {finding('CHECK','UNKNOWN: symlink manifest has invalid format.');exit;}
    for my $f(keys %{$manifest->{symlinks}}) {
        if (!$inside->($f) || $f =~ /[\x00-\x1f]/ || $f =~ m{(?:^|/)\.\.?(/|$)} ||
            !defined($manifest->{symlinks}{$f}) || ref($manifest->{symlinks}{$f})) {
            finding('CHECK','UNKNOWN: symlink manifest path/target invalid or outside roots.');exit;
        }
    }
}
eval {
    File::Find::find({no_chdir=>1,wanted=>sub {
        my $f=$File::Find::name;

        if (exists($manifest->{files}{$f}) && !-f $f || exists($manifest->{files}{$f}) && -l $f) {
            $type_changed++ unless $type_seen{$f}++;my $safe=$f;$safe =~ s/[^A-Za-z0-9_.\/-]/?/g;
            finding('CHECK',"Baseline regular file has another file type: $safe") if $type_changed<=100;
        }
        if (-l $f) {
            die "symlink limit\n" if ++$link_count>1000;
            $links_seen{$f}=1;
            my $target=readlink($f);
            my $safe=$f;$safe =~ s/[^A-Za-z0-9_.\/-]/?/g;
            if (!defined($target)) {$partial++;finding('CHECK',"Symlink unreadable: $safe");return;}
            my $expected=ref($manifest->{symlinks}) eq 'HASH' ? $manifest->{symlinks}{$f}:undef;
            my $state;
            if (!defined($expected)) {$link_unknown++;$state='NO_TARGET_BASELINE';}
            elsif ($target ne $expected) {$link_changed++;$state='TARGET_CHANGED';}
            else {$state='TARGET_MATCH';}
            my $resolved=Cwd::abs_path($f);
            if (!-e $f || !defined($resolved)) {$state.='; DANGLING_OR_UNRESOLVED';}
            elsif (!$inside->($resolved)) {$state.='; RESOLVES_OUTSIDE_SCAN_ROOTS';}
            my $display=$target;$display =~ s/[^A-Za-z0-9_.:\/-]/?/g;$display=substr($display,0,200);
            finding('CHECK',"Symlink $safe -> $display: $state; target contents not followed.") if $link_count<=100;
            return;
        }
        return unless -f $f;

        die "limit\n" if ++$scanned>50000;
        $observed{$f}=1;
        if (exists($manifest->{files}{$f})) {
            my $meta=ref($manifest->{file_metadata}) eq 'HASH' ? $manifest->{file_metadata}{$f}:undef;
            if (ref($meta) eq 'HASH' && defined($meta->{mode}) && $meta->{mode}=~/^[0-7]{3,4}$/) {
                my @st=lstat($f);
                if (@st) {
                    $mode_checked++;my $actual=sprintf('%04o',$st[2]&07777);
                    my $expected=sprintf('%04o',oct($meta->{mode}));
                    if ($actual ne $expected) {
                        $mode_changed++;my $safe=$f;$safe =~ s/[^A-Za-z0-9_.\/-]/?/g;
                        finding('CHECK',"File permission drift: $safe expected=$expected observed=$actual (includes setuid/setgid/sticky bits).") if $mode_changed<=100;
                    }
                } else {$partial++;}
            } else {$mode_unknown++;}
        }

        if (-s $f>128*1024*1024) {$partial++;return;}
        my $hash=cached_digest($f,0);
        if (!$hash) {$partial++;return;}
        my $kind;
        if (!exists $manifest->{files}{$f}) {$new++;$kind='NEW';}
        elsif (lc($manifest->{files}{$f}) ne $hash) {$changed++;$kind='CHANGED';}
        if ($kind && variable_path($f)) {
            if ($kind eq 'NEW') {$new--;$variable_new++;}
            else {$changed--;$variable_changed++;}
            # Still compared and counted: cache-shaped paths are never exempt from IoC checks.
            return;
        }
        if ($kind && $new+$changed<=100) {my $safe=$f;$safe =~ s/[^A-Za-z0-9_.\/-]/?/g;finding('CHECK',"$kind file relative to approved manifest: $safe");}
    }},@roots);1;
} or $partial++;
for my $f(keys %{$manifest->{files}}) {
    if (!exists $observed{$f}) {
        if ($scanned>50000) {$partial++;next;}
        if (-e $f || -l $f) {
            if (!-f $f && !-l $f && !$type_seen{$f}++) {$type_changed++;}
            $partial++;next;
        }
        if (variable_path($f)) {$variable_missing++;next;}
        $missing++; if ($missing<=100) {my $safe=$f;$safe =~ s/[^A-Za-z0-9_.\/-]/?/g;finding('CHECK',"MISSING baseline file: $safe");}
    }
}

if (ref($manifest->{symlinks}) eq 'HASH') {
    for my $f(keys %{$manifest->{symlinks}}) {
        next if $links_seen{$f};
        if ($partial || $scanned>50000 || $link_count>1000) {next;}
        $link_missing++;my $safe=$f;$safe =~ s/[^A-Za-z0-9_.\/-]/?/g;
        finding('CHECK',"Baseline symlink missing or replaced by another file type: $safe") if $link_missing<=100;
    }
}
finding('CHECK',"Symlink coverage: observed=$link_count, changed targets=$link_changed, no target baseline=$link_unknown, missing/replaced=$link_missing. Targets inventoried without following contents; at most 100 rows displayed, 1000 links scanned. Old manifests have no link-target baseline.") if $link_count || $link_missing || !exists($manifest->{symlinks});
finding('CHECK',"Variable Python-cache baseline differences: new=$variable_new, changed=$variable_changed, missing=$variable_missing; retained as review counts, not declared benign. Non-cache scripts and customizations remain in detailed findings.") if $variable_new+$variable_changed+$variable_missing;
finding(($mode_changed||$type_changed||$mode_unknown)?'CHECK':'OK',"File metadata coverage: mode_checked=$mode_checked, mode_changed=$mode_changed, type_changed=$type_changed, missing_mode_reference=$mode_unknown. Ownership/timestamps are not compared; differences need approved-change review.");
finding(($partial||$new||$changed||$missing||$mode_changed||$type_changed)?'CHECK':'OK',"Approved file baseline: scanned=$scanned, new=$new, changed=$changed, missing=$missing, incomplete=$partial. Scope is declared roots; provenance/approval remain operator assertions. Differences are not proof of compromise.");
DEYDA_COVERAGE_PERL
else
    status CHECK 'UNKNOWN: Perl unavailable for log timestamp and file-manifest coverage.'
fi


subsection 'SAML reconnaissance: probe User-Agent, oversized requests, and reported source range' 'DEYDA-0049'
printf '%s\n' 'These community-reported patterns are hunting leads, not Citrix-published IoCs. A match needs timestamp, source, request, and authentication/crash correlation.'
SAML_PROBE_HITS=$(zgrep -E -i -n '"probe/1"|"(GET|POST|HEAD) /(saml/login|cgi/samlauth)' /var/log/httpaccess* 2>/dev/null \
    | awk 'tolower($0) ~ /probe\/1/ || (tolower($0) ~ /"(get|post|head) \/(saml\/login|cgi\/samlauth)/ && length($0) > 2500)' \
    | chrono_sort | tail -30)
if [ -n "$SAML_PROBE_HITS" ]; then
    status CHECK 'SAML access logs contain the reported probe/1 User-Agent or a request longer than 2500 characters to /saml/login or /cgi/samlauth. This is a hunting lead, not proof of exploitation; correlate source, time, nsaaad events, and sign-in outcome:'
    printf '%s\n' "$SAML_PROBE_HITS" | cut -c1-320
elif [ "$RECON_LOGS_FOUND" -eq 0 ]; then
    status CHECK 'No readable HTTP access logs are available for the SAML reconnaissance check.'
else
    status OK 'No probe/1 User-Agent or selected oversized SAML request found in retained HTTP access logs; other formats and rotated-out logs are outside coverage.'
fi
GOTHAM_SAML_RANGE_HITS=$(zgrep -E -i -n '(^|[^0-9.])138[.]199[.]60[.]([0-9]{1,3})([^0-9]|$)' \
    /var/log/httpaccess* /var/log/httperror* /var/log/httperror-vpn* /var/log/ns.log* /var/log/messages* /var/log/notice.log* /var/log/nsvpn.log* 2>/dev/null \
    | chrono_sort | tail -30)
if [ -n "$GOTHAM_SAML_RANGE_HITS" ]; then
    status CHECK 'Log lines contain an address in the community-reported 138.199.60.0/24 range. This range may include shared VPN/hosting infrastructure; treat it as a correlation lead, not attribution or an automatic block recommendation:'
    printf '%s\n' "$GOTHAM_SAML_RANGE_HITS" | cut -c1-320
elif [ "$RECON_LOGS_FOUND" -eq 0 ]; then
    status CHECK 'No readable candidate HTTP logs are available for the reported SAML source-range check; system-log coverage may still have been searched above.'
else
    status OK 'No 138.199.60.0/24 address found in the selected retained logs. This is limited to searched files and retention.'
fi
subsection 'Authentication endpoint requests and payload combinations' 'DEYDA-0050'
EXPLOIT_PATH_HITS=$(zgrep -E -i -n '(/nitro/v1/config/login|/nf/auth/(doAuthentication|getAuthenticationRequirements)[.]do|/vpn/index[.]html|/logon/LogonPoint/(index[.]html|tmindex[.]html|Authentication/GetUserName)|/cgi/login|/p/u/do(Authentication|Logon)[.]do)' /var/log/httpaccess* /var/log/httperror* /var/log/httperror-vpn* 2>/dev/null | chrono_sort | tail -40)
EXPLOIT_PATH_COUNT=$(zgrep -E -i -c '(/nitro/v1/config/login|/nf/auth/(doAuthentication|getAuthenticationRequirements)[.]do|/vpn/index[.]html|/logon/LogonPoint/(index[.]html|tmindex[.]html|Authentication/GetUserName)|/cgi/login|/p/u/do(Authentication|Logon)[.]do)' /var/log/httpaccess* /var/log/httperror* /var/log/httperror-vpn* 2>/dev/null | awk -F: '{n += $NF} END {print n+0}')
AUTH_POISON_HTTP_HITS=$(zgrep -E -i -n '(/nitro/v1/config/login|/nf/auth/(doAuthentication|getAuthenticationRequirements)[.]do|/vpn/index[.]html|/logon/LogonPoint/(index[.]html|tmindex[.]html|Authentication/GetUserName)|/cgi/login|/p/u/do(Authentication|Logon)[.]do)[^[:cntrl:]]*(pitboss|NSPPE|PPE unexpectedly died|missed too many heartbeats|%3[bB]|%60|\$\{IFS\}|curl[[:space:]]|wget[[:space:]]|fetch[[:space:]])' /var/log/httpaccess* /var/log/httperror* /var/log/httperror-vpn* 2>/dev/null | chrono_sort | tail -30)
if [ -n "$EXPLOIT_PATH_HITS" ]; then
    if [ -n "$AUTH_POISON_HTTP_HITS" ]; then
        status OK "$EXPLOIT_PATH_COUNT request line(s) to monitored authentication endpoints inventoried. Routine endpoint use is expected; up to 30 recent suspicious matches are shown below, with other overlapping copies suppressed."
    else
        status OK "$EXPLOIT_PATH_COUNT request line(s) to monitored authentication endpoints inventoried; no selected shell/log-poisoning marker found. Endpoint use alone is expected and is not an IOC."
    fi
else
    status OK 'No requests to selected public exploit/authentication paths found in available HTTP logs; this is limited by log retention and format.'
fi
if [ -n "$AUTH_POISON_HTTP_HITS" ]; then
    status ACTION 'A logged exploit-path request also contains a public log-poisoning trigger or shell/download marker. Review the full request and correlate with ns.log/messages and file artifacts; this indicates an attempt, not automatically successful execution:'
    printf '%s\n' "$AUTH_POISON_HTTP_HITS"
fi

subsection 'SOCRadar CVE-2026-88771 C2, delayed execution, and agent artifacts' 'DEYDA-0051'
printf '%s\n' 'SOCRadar reports a separate automated C2 operation. A matching login/log line indicates an attempt; a C2 address/path or agent artifact is a higher-priority lead, but none alone proves command execution or data theft.'
SOCRADAR_LOGS_FOUND=0
for f in /var/log/ns.log* /var/log/messages* /var/log/notice.log* /var/log/nsvpn.log* /var/log/auth.log* /var/log/sh.log* /var/log/bash.log* /var/log/httpaccess* /var/log/httperror* /var/log/httperror-vpn* /var/log/named* /var/log/dns*; do
    [ -f "$f" ] && [ -r "$f" ] && SOCRADAR_LOGS_FOUND=1
done
SOCRADAR_TRIGGER_HITS=$(zgrep -E -i -n 'pitboss[[:space:]]+NSPPE(-[0-9]+)?;[^[:cntrl:]]*(curl|wget|fetch|nslookup|%24%7BIFS%7D|\$\{IFS\})[^[:cntrl:]]*;#[[:space:]]*unexpectedly died|pitboss[[:space:]]+NSPPE(-[0-9]+)?;[^[:cntrl:]]*;#[[:space:]]*unexpectedly died' \
    /var/log/ns.log* /var/log/messages* /var/log/notice.log* /var/log/nsvpn.log* /var/log/auth.log* /var/log/sh.log* /var/log/bash.log* /var/log/httpaccess* /var/log/httperror* /var/log/httperror-vpn* 2>/dev/null | chrono_sort | tail -30)
if [ -n "$SOCRADAR_TRIGGER_HITS" ]; then
    SOCRADAR_TRIGGER_LINES=$(printf '%s\n' "$SOCRADAR_TRIGGER_HITS" | wc -l | tr -d ' ')
    status ACTION "SOCRadar-style pitboss NSPPE-00;...;# unexpectedly died pattern found in up to 30 recent log lines ($SOCRADAR_TRIGGER_LINES shown). The full injection evidence is grouped in the CVE-2026-88771 attack-chain analysis above; this cross-check does not repeat raw log entries."
elif [ "$SOCRADAR_LOGS_FOUND" -eq 0 ]; then
    status CHECK 'No readable candidate logs were available for the SOCRadar-specific injection-pattern check.'
else
    status OK 'No SOCRadar-specific pitboss NSPPE-00;...;# unexpectedly died pattern found in the retained candidate logs. Other encodings and removed logs are outside coverage.'
fi

SOCRADAR_C2_HITS=$(zgrep -E -i -n '(^|[^0-9.])45[.]143[.]130[.]195([^0-9.]|$)|/s/[[:xdigit:]]{8}([^[:alnum:]_]|$)|/a/[[:xdigit:]]{8}([^[:alnum:]_]|$)|/p/[[:xdigit:]]{8}[?]|/c/[[:xdigit:]]{8}([^[:alnum:]_]|$)|/r/[[:xdigit:]]{8}[?]|p1[.]oob[.]45[.]143[.]130[.]195' \
    /var/log/httpaccess* /var/log/httperror* /var/log/httperror-vpn* /var/log/ns.log* /var/log/messages* /var/log/notice.log* /var/log/nsvpn.log* /var/log/auth.log* /var/log/sh.log* /var/log/bash.log* /var/log/named* /var/log/dns* 2>/dev/null | chrono_sort | tail -40)
if [ -n "$SOCRADAR_C2_HITS" ]; then
    status ACTION 'SOCRadar-reported C2 address, DNS beacon, or callback-path indicator found in retained logs. This is a high-priority lead, not proof by itself that the agent ran or a transfer succeeded. Preserve evidence and verify origin, direction, destination port, and timestamps: '
    printf '%s\n' "$SOCRADAR_C2_HITS" | cut -c1-360
elif [ "$SOCRADAR_LOGS_FOUND" -eq 0 ]; then
    status CHECK 'No readable candidate logs were available for the SOCRadar C2 indicator check.'
else
    status OK 'No SOCRadar C2 address, DNS beacon, or selected callback-path indicator found in retained candidate logs. Historical egress may only exist in external firewall, DNS, or proxy telemetry.'
fi

NSAGENT_FILES=$(find /tmp /var/tmp -maxdepth 3 -type f -name '.nsagent' -print 2>/dev/null | head -30)
NSAGENT_PROCESSES=$(ps auxww 2>/dev/null | grep -E '[ /]tmp/[.]nsagent([[:space:]]|$)|[ /]var/tmp/[.]nsagent([[:space:]]|$)' | grep -v '[g]rep')
if [ -n "$NSAGENT_FILES" ] || [ -n "$NSAGENT_PROCESSES" ]; then
    status ACTION 'The SOCRadar-reported .nsagent file or process was found under a temporary path. Preserve the file, metadata, process and socket evidence; do not execute or delete it.'
    [ -n "$NSAGENT_FILES" ] && printf 'Files:\n%s\n' "$NSAGENT_FILES"
    [ -n "$NSAGENT_PROCESSES" ] && printf 'Processes:\n%s\n' "$NSAGENT_PROCESSES"
else
    status OK 'No /tmp/.nsagent or /var/tmp/.nsagent file/process found in the checked scope. Renamed, deleted, or differently staged agents are outside this filename check.'
fi

if command -v sockstat >/dev/null 2>&1; then
    SOCRADAR_SOCKET_HITS=$(sockstat -4 -c 2>/dev/null | grep -E '(^|[[:space:]])45[.]143[.]130[.]195:(8899|53)([[:space:]]|$)')
    if [ -n "$SOCRADAR_SOCKET_HITS" ]; then
        status ACTION 'A current IPv4 client socket references the SOCRadar-reported C2 address on port 8899 or 53. Preserve PID/socket details and investigate immediately; this is only a point-in-time socket snapshot:'
        printf '%s\n' "$SOCRADAR_SOCKET_HITS"
    else
        status CHECK 'No current sockstat connection to 45.143.130[.]195 on ports 8899/53 was observed. This point-in-time check cannot rule out earlier connections or DNS activity.'
    fi
else
    status CHECK 'sockstat is unavailable; current SOCRadar C2 socket state was not checked.'
fi
printf '%s\n' 'Correlation guidance: SOCRadar attributes delayed processing to admautoregd and reports a possible delay of up to 24 hours or processing after a reboot. For each matching injection, review HTTP, shell, DNS, firewall/proxy, reboot and file/process evidence through the following 24 hours. This report identifies co-occurring indicators but does not infer that time relationship across all external telemetry.'

