subsection 'Bootstrap and downloader log markers' 'DEYDA-0054'
BOOTSTRAP_LOG_COUNTS=$(zgrep -hE '/api/v1/install/|PLATYPUS_INGRESS_CA|AGENT_TOKEN|plt_[[:alnum:]]{12,}[.]|fetch([^[:cntrl:]]{0,40})-qo[[:space:]]+/v([[:space:]]|$)|:443/t/[[:xdigit:]]{6}' \
