    awk '{total++; if (/\/api\/v1\/install\//) bootstrap++; if (/PLATYPUS_INGRESS_CA|AGENT_TOKEN|plt_/) token++; if (/fetch|:443\/t\//) download++} END {printf "%d %d %d %d", total, bootstrap, token, download}')
