subsection 'Administrative-account and EPA modification audit evidence' 'DEYDA-0058'
ACCESS_AUDIT_FOUND=0
ACCESS_AUDIT_HITS=0
for f in /var/log/ns.log* /var/log/messages* /var/log/notice.log* /var/log/nsvpn.log* /var/log/sh.log* /var/log/bash.log* /var/log/audit.log*; do
    [ -f "$f" ] && [ -r "$f" ] || continue
    ACCESS_AUDIT_FOUND=$((ACCESS_AUDIT_FOUND + 1))
    ACCESS_AUDIT_PATTERN='(add|set|rm)[[:space:]]+system[[:space:]]+user|bind[[:space:]]+system[[:space:]]+(user|group)|set[[:space:]]+authentication[[:space:]]+epaAction.*defaultEPAGroup|unbind[[:space:]]+(authentication[[:space:]]+(vserver|policylabel)|vpn[[:space:]]+vserver)|save[[:space:]]+ns[[:space:]]+config'
    case "$f" in
        *.gz) ACCESS_FILE_HITS=$(zgrep -E -i -n "$ACCESS_AUDIT_PATTERN" "$f" 2>/dev/null | tail -40) ;;
        *) ACCESS_FILE_HITS=$(grep -E -i -n "$ACCESS_AUDIT_PATTERN" "$f" 2>/dev/null | tail -40) ;;
    esac
    if [ -n "$ACCESS_FILE_HITS" ]; then
        ACCESS_AUDIT_HITS=$((ACCESS_AUDIT_HITS + 1))
        status CHECK "Selected administrative/authentication change commands occur in $f (up to 40 matches). Validate operator, source, result code, timestamp/timezone, approved changes, and effective bindings. These lines are not automatically one transaction or proof of execution:"
        # Omit whole matched command tails when they could contain user credentials.
        printf '%s\n' "$ACCESS_FILE_HITS" | awk '{
            lower=tolower($0)
            if(match(lower, /(add|set)[[:space:]]+system[[:space:]]+user/))
                print substr($0,1,RSTART-1) "[system-user command details omitted: may contain credentials]"
            else print $0
        }'
    fi
done
if [ "$ACCESS_AUDIT_FOUND" -eq 0 ]; then
    status CHECK 'No readable candidate administrative/system/shell audit logs found; account/EPA change-history coverage is unavailable.'
elif [ "$ACCESS_AUDIT_HITS" -eq 0 ]; then
    status OK 'No selected account/EPA modification commands found in retained candidate logs. Local logs can omit changes or rotate; review remote audit/SIEM records as well.'
fi
printf '%s\n' 'Follow-up: correlate user creation and rights bindings with EPA changes/unbinds and config-save events at matching times and from the same operator/source. Review remote audit and approved change records; this check performs keyword extraction, not automatic transaction correlation.'

printf '\n--- Suspicious command patterns in shell audit logs ---\n'
SHELL_AUDIT_LOGS_FOUND=0
SHELL_AUDIT_HITS=''
for f in /var/log/sh.log* /var/log/bash.log*; do
    [ -f "$f" ] && [ -r "$f" ] || continue
    SHELL_AUDIT_LOGS_FOUND=1
    case "$f" in
        *.gz) matches=$(zgrep -E -i -n 'database\.php|/flash/nsconfig/keys|LDAPTLS_REQCERT|ldapsearch|(^|[[:space:]])openssl([[:space:]]|$)|/nsconfig/ns\.conf|/etc/auth\.conf|cp /usr/bin/bash|F1\.key|F2\.key|nobody|(^|[^[:alnum:]_])id([^[:alnum:]_]|$)|curl[[:space:]]|wget[[:space:]]|fetch[[:space:]]|/ns_gui/vpn|/var/netscaler/logon|/var/vpn|/var/tmp' "$f" 2>/dev/null | tail -50) ;;
        *) matches=$(grep -E -i -n 'database\.php|/flash/nsconfig/keys|LDAPTLS_REQCERT|ldapsearch|(^|[[:space:]])openssl([[:space:]]|$)|/nsconfig/ns\.conf|/etc/auth\.conf|cp /usr/bin/bash|F1\.key|F2\.key|nobody|(^|[^[:alnum:]_])id([^[:alnum:]_]|$)|curl[[:space:]]|wget[[:space:]]|fetch[[:space:]]|/ns_gui/vpn|/var/netscaler/logon|/var/vpn|/var/tmp' "$f" 2>/dev/null | tail -50) ;;
    esac
    if [ -n "$matches" ]; then SHELL_AUDIT_HITS="$SHELL_AUDIT_HITS\n--- $f ---\n$matches"; fi
done
if [ -n "$SHELL_AUDIT_HITS" ]; then status CHECK 'Command-pattern matches found in available shell audit logs; these are heuristic and need contextual review:'; printf '%b\n' "$SHELL_AUDIT_HITS" | head -120; elif [ "$SHELL_AUDIT_LOGS_FOUND" -eq 1 ]; then status OK 'No configured command patterns found in readable shell audit logs.'; else status CHECK 'No readable sh.log/bash.log files found; shell command-history coverage is unknown.'; fi

printf '\n--- Gateway/VPN access-log session indicators ---\n'
VPN_ACCESS_FILES_FOUND=0
for f in /var/log/httpaccess-vpn.log*; do [ -f "$f" ] && [ -r "$f" ] && VPN_ACCESS_FILES_FOUND=1; done
VPN_200_NO_RECEIVER=$(zgrep -E -v 'CitrixReceiver' /var/log/httpaccess-vpn.log* 2>/dev/null | grep ' 200 ' | chrono_sort | tail -50)
VPN_HEADLESS=$(zgrep -E -i -n 'HeadlessChrome' /var/log/httpaccess-vpn.log* 2>/dev/null | chrono_sort | tail -50)
if [ "$VPN_ACCESS_FILES_FOUND" -eq 0 ]; then
    status CHECK 'No readable httpaccess-vpn.log files found; Gateway/VPN session-log checks have no coverage.'
else
    if [ -n "$VPN_200_NO_RECEIVER" ]; then
        status CHECK 'HTTP 200 VPN-access lines without a CitrixReceiver marker found. Browser/clientless sessions can be legitimate; correlate user/session, source address, user-agent, and authentication result:'
        printf '%s\n' "$VPN_200_NO_RECEIVER"
    else
        status OK 'No HTTP 200 VPN-access lines without a CitrixReceiver marker found in retained logs.'
    fi
    if [ -n "$VPN_HEADLESS" ]; then
        status CHECK 'HeadlessChrome user-agent lines found in VPN access logs; validate whether browser automation or a supported client explains them:'
        printf '%s\n' "$VPN_HEADLESS"
    else
        status OK 'No HeadlessChrome user-agent lines found in retained VPN access logs.'
    fi
fi
status CHECK 'The script does not reconstruct sessions across changing source IPs/countries/user-agents or determine whether sessions remained valid after password/MFA changes; perform that correlation in Gateway/AAA telemetry or SIEM.'

printf '\n--- Current network-connection snapshot ---\n'
if command -v sockstat >/dev/null 2>&1; then
    CURRENT_CONNECTIONS=$(sockstat -4 -c 2>&1 | head -80)
elif command -v netstat >/dev/null 2>&1; then
    CURRENT_CONNECTIONS=$(netstat -an 2>&1 | head -80)
else
    CURRENT_CONNECTIONS=''
fi
if [ -n "$CURRENT_CONNECTIONS" ]; then
    status CHECK 'Point-in-time network connections are listed for review; distinguish expected NetScaler traffic from unexpected outbound connections, internal scans, tunnels, or data transfers:'
    printf '%s\n' "$CURRENT_CONNECTIONS"
else
    status CHECK 'No supported socket/network inventory utility returned data; inspect network telemetry outside the appliance.'
fi
status CHECK 'Firewall, DNS, SMB/LDAP/Kerberos/RDP, traffic-volume, and internal-scan history require external network/firewall/SIEM telemetry and are not inferred from this connection snapshot.'


section '6. Post-scan validation' 'DEYDA-0059'
printf '%s\n' 'Complete these vendor-supported validation steps separately; this read-only helper does not perform them.'
subsection 'Firewall containment reminder: reported payload IP' 'DEYDA-0060'
status CHECK 'BLOCKING RECOMMENDATION: block 213.209.159.55 on upstream firewalls for inbound access to public NetScaler VIPs and outbound connections from the appliance (NSIP/SNIP, including TCP 443). Validate and document the rule with the security team; this script cannot inspect or confirm upstream firewall enforcement.'
printf '%s\n' 'Context: the IP is a reported payload destination. The operator-provided community comment also describes it as an incoming attack source; that attribution is not independently verified here. An IP reference inside a crafted username does not identify the incoming request source.'
printf '%s\n' 'Port 443 may carry plain HTTP in this reported activity. An IP block does not replace patching or incident investigation; delivery infrastructure can change. The SAML responder workaround is an interim mitigation for affected builds and is not required once the applicable CVE-2026-88779 fixed build is installed. No firewall/ADC configuration is modified by this script.'

subsection 'File Integrity Monitoring' 'DEYDA-0061'
status CHECK 'Run the supported Citrix/NetScaler File Integrity Monitoring scan and compare results with a known-good baseline; this script does not run that scan.'
else
section 'Appliance-only checks' 'DEYDA-0062'
status CHECK 'Skipped: this run targets an exported configuration file. Run the script locally on each ADC to scan logs, files, reboots, and other host indicators.'
fi

section '7. Incident response guidance — use if compromise is suspected' 'DEYDA-0063'
cat <<'IRGUIDE'
These are response reminders, not automated actions. Follow your incident-response process and coordinate with security, operations, and legal teams as appropriate.

1. Preserve evidence before changing the appliance: for VPX, coordinate a hypervisor snapshot; record system time, timezone, and NTP configuration; preserve local, remote syslog, and NetScaler Console logs. Generate a support bundle.
2. NSPPE core-dump collection causes a warm restart and disconnects SSH. Do not start it casually: first preserve other available evidence and coordinate the required restart with incident response and service owners. Preserve NSPPE core files for offline analysis.
3. Contain suspected compromise by isolating the appliance as directed by the incident-response lead, considering service impact. Investigate connected authentication, web, management, and application systems for lateral activity.
4. If compromise is confirmed, plan a trusted rebuild/replacement rather than relying on patching or deleting suspicious files. Restore only a known-good configuration backup that predates compromise, then validate the configuration.
5. Revoke or rotate secrets and credentials stored on or used through the appliance, including service-account credentials, shared secrets, API keys, and affected user accounts. Revoke certificates/private keys as appropriate; after rebuild, rotate local passwords and key-encryption keys and replace revoked certificates.
6. Harden the rebuilt system, keep NetScaler management services off the public internet, and monitor closely for at least 90 days. Preserve chain-of-custody evidence if legal or law-enforcement action may follow.

Citrix guidance: https://support.citrix.com/external/article/CTX694799/steps-to-take-if-netscaler-adc-is-suspec.html
IRGUIDE

# Put a concise, scan-derived summary before the detailed sections. Exact
# numbered config rows and exact log records repeated across different
# subsections are printed once; repeated occurrences within one log check stay.
# The overview names affected report areas only; evidence and recommendations
# remain in their detailed section.
DEDUP_TMP=$(mktemp "${OUT}.dedup.XXXXXX" 2>/dev/null)
DEDUP_COUNT_TMP=$(mktemp "${OUT}.dedupcount.XXXXXX" 2>/dev/null)
DUPLICATE_LOG_LINES=0
if [ -n "$DEDUP_TMP" ] && [ -n "$DEDUP_COUNT_TMP" ]; then
    if awk -v count_file="$DEDUP_COUNT_TMP" '
        function is_config(s) {return s ~ /^[0-9]+:(add|set|bind|unbind|rm|delete|enable|disable) /}
        function is_log(s) {
            return s ~ /^\/var\/(log|nslog)\/[^[:space:]]+:[0-9]+:/ ||
                   s ~ /^[0-9]+:(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[[:space:]]/ ||
                   s ~ /^[0-9]+:[0-9]{4}-[0-9]{2}-[0-9]{2}[ T]/ ||
                   s ~ /^[0-9]+:[0-9]{1,3}[.][0-9]{1,3}[.][0-9]{1,3}[.][0-9]{1,3}[[:space:]]/}
        /^===== / {major=$0; minor=""}
        /^--- / {minor=$0}
        {
            scope=major " " minor
            if (is_config($0)) {
                if (seen_config[$0]++) next
            } else if (is_log($0)) {
                if (($0 in first_scope) && first_scope[$0] != scope) {suppressed++; next}
                if (!($0 in first_scope)) first_scope[$0]=scope
            }
            print
        }
        END {print suppressed+0 > count_file}
    ' "$OUT" > "$DEDUP_TMP"; then
        mv "$DEDUP_TMP" "$OUT"
        DUPLICATE_LOG_LINES=$(cat "$DEDUP_COUNT_TMP" 2>/dev/null)
        rm -f "$DEDUP_COUNT_TMP"
    else
        rm -f "$DEDUP_TMP" "$DEDUP_COUNT_TMP"
    fi
else
    [ -n "$DEDUP_TMP" ] && rm -f "$DEDUP_TMP"
    [ -n "$DEDUP_COUNT_TMP" ] && rm -f "$DEDUP_COUNT_TMP"
fi
ACTION_COUNT=$(awk '/^===== 1[.] Platform and uptime =====/{scan=1; next} scan && /^\[ACTION\]/{n++} END{print n+0}' "$OUT")
CHECK_COUNT=$(awk '/^===== 1[.] Platform and uptime =====/{scan=1; next} scan && /^\[CHECK\]/{n++} END{print n+0}' "$OUT")
SUMMARY_TMP=$(mktemp "${OUT}.summary.XXXXXX" 2>/dev/null)
REPORT_TMP=$(mktemp "${OUT}.final.XXXXXX" 2>/dev/null)
if [ -n "$SUMMARY_TMP" ] && [ -n "$REPORT_TMP" ]; then
    {
        printf '===== Assessment overview =====\n'
        printf 'OUTCOME: '
        if [ "$ACTION_COUNT" -gt 0 ]; then
            printf '%s\n' 'INVESTIGATION REQUIRED — selected high-priority indicators matched; this alone does not prove successful execution or compromise.'
        elif [ "$CHECK_COUNT" -gt 0 ]; then
            printf '%s\n' 'MANUAL REVIEW REQUIRED — no selected ACTION indicator matched, but CHECK items or coverage gaps remain.'
        else
            printf '%s\n' 'NO SELECTED FINDINGS — this is not proof that the appliance is clean; verify scan coverage and external telemetry.'
        fi
        if [ "${DUPLICATE_LOG_LINES:-0}" -gt 0 ]; then
            printf 'Exact log-evidence rows repeated across subsections: %s suppressed; the first copy is retained.\n' "$DUPLICATE_LOG_LINES"
        fi
        if [ "$ACTION_COUNT" -gt 0 ]; then
            printf '\nACTION FOUND IN\n'
            awk '
                {sub(/\r$/, "")}
                /^===== 1[.] Platform and uptime =====$/ {scan=1; next}
                !scan {next}
                /^===== / {major=$0; sub(/^===== /,"",major); sub(/ =====$/,"",major); next}
                /^\[ACTION\]/ && major!="" && !seen[major]++ {print "  - " major}
            ' "$OUT"
        fi
        if [ "$CHECK_COUNT" -gt 0 ]; then
            printf '\nMANUAL REVIEW NEEDED IN\n'
            awk '
                {sub(/\r$/, "")}
                /^===== 1[.] Platform and uptime =====$/ {scan=1; next}
                !scan {next}
                /^===== / {major=$0; sub(/^===== /,"",major); sub(/ =====$/,"",major); next}
                /^\[CHECK\]/ && major!="" && !seen[major]++ {print "  - " major}
            ' "$OUT"
        fi
        printf '\nSCAN COVERAGE\n'
        awk '
          /^--- / {scope=$0}
          scope ~ /Saved versus running configuration/ && /^(Evidence source:|\[CHECK\] UNKNOWN:|SAML objects)/ {print "  " $0}
          scope ~ /Evidence coverage: retained log timestamps/ && /\[(CHECK|OK)\].*(Log coverage:|UNKNOWN:|Approved file baseline:|exceeded 60 seconds)/ {print "  " $0}
        ' "$OUT"
        printf '%s\n' '  Symlink targets are inventoried and compared when present in the manifest; target contents are not followed; timestamp ranges do not prove log continuity.'
        printf '\n%s\n' 'The lists above point to report sections; each finding, evidence item, and recommended response is detailed once in its section below.'
        printf '\n'
    } > "$SUMMARY_TMP"
    awk -v summary="$SUMMARY_TMP" '
        {sub(/\r$/, "")}
        /^===== How to read this report =====$/ {
            while ((getline line < summary) > 0) print line
            close(summary)
            print ""
        }
        {print}
    ' "$OUT" > "$REPORT_TMP" && mv "$REPORT_TMP" "$OUT"
    rm -f "$SUMMARY_TMP" "$REPORT_TMP"
else
    [ -n "$SUMMARY_TMP" ] && rm -f "$SUMMARY_TMP"
    [ -n "$REPORT_TMP" ] && rm -f "$REPORT_TMP"
    printf '%s\n' 'Executive summary could not be inserted; detailed report remains available.'
fi



# Export fixed group IDs; individual messages remain evidence within each group.
# IDs are literal arguments at section/subsection callsites: preserve them on edits.
if command -v perl >/dev/null 2>&1; then
    perl - "$OUT" "$OUT.json" "$SCRIPT_VERSION" "$CURRENT_INPUT" "$HOST" <<'DEYDA_JSON_PERL'
use strict;use warnings;use JSON::PP;use Digest::SHA qw(sha256_hex);
my($report,$json,$version,$build,$host)=@ARGV;
my $data={schema=>'deyda-ioc-v1',script_version=>$version,build=>$build,evidence_source=>'UNKNOWN',enhanced_isn=>'UNKNOWN'};
if (-f $json) {eval {open my $f,'<',$json or die;local $/;$data=decode_json(<$f>);close $f;1};}
$data->{schema}='deyda-ioc-v1';$data->{script_version}=$version;$data->{build}=$build;$data->{hostname}=$host;
$data->{check_id_scheme}='deyda-group-v1';$data->{generated_at_epoch}=time;
$data->{findings}=[];$data->{coverage}=[];$data->{checks}=[];
my $partition=$ENV{DEYDA_PARTITION_LABEL}//'UNKNOWN';
$partition='UNKNOWN' unless $partition=~/^[A-Za-z0-9_.-]{1,64}$/;
$data->{conditions}={schema=>'deyda-conditions-v1',partition=>$partition,partition_source=>'operator_label',
    runtime_source=>$data->{evidence_source}//'UNKNOWN',baseline_sha256=>'UNKNOWN',baseline_source=>'UNKNOWN',
    scan_limits=>'UNKNOWN',config_baseline_sha256=>'NONE'};
if (my $config_baseline=$ENV{DEYDA_CONFIG_BASELINE}) {
    $data->{conditions}{config_baseline_sha256}='UNKNOWN';
    eval {open my $cb,'<',$config_baseline or die;binmode $cb;my $digest=Digest::SHA->new(256)->addfile($cb)->hexdigest;close $cb;$data->{conditions}{config_baseline_sha256}=$digest;1};
}

open my $fh,'<',$report or exit 1;
my($section,$subsection,$id)=('Report','','');my (%seen,%groups);
my %rank=(OK=>0,CHECK=>1,ACTION=>2,SUSPECT=>2,TARGETED=>2);
while(my $line=<$fh>) {
    if ($line =~ /Coverage-Condition: (baseline_sha256|baseline_source|scan_limits)=([A-Za-z0-9_-]+)/) {
        $data->{conditions}{$1}=$2;
    }

    if ($line =~ /(?:Log coverage:|Symlink coverage:|File metadata coverage:|Approved file baseline:|UNKNOWN: running configuration|UNKNOWN: configuration tokenization|coverage.file-baseline scan exceeded|Variable Python-cache baseline differences:)/) {
        chomp(my $cl=$line);$cl =~ s/^\s+|\s+$//g;
        push @{$data->{coverage}},$cl unless grep {$_ eq $cl} @{$data->{coverage}};
    }
    if ($line =~ /^===== (.*?) =====/) {$section=$1;$subsection='';$id='';}
    if ($line =~ /^--- (.*?) ---/) {$subsection=$1;$id='';}
    if ($line =~ /^Check-ID: (DEYDA-\d{4})\s*$/) {
        $id=$1;$groups{$id}//={check_id=>$id,section=>$section,check=>$subsection,status=>'NOT_ASSESSED',finding_count=>0};
    }
    next unless $id && $line =~ /^\[(OK|CHECK|ACTION|SUSPECT|TARGETED)\]\s+(.*)/;
    my($status,$message)=($1,$2);
    my $evidence_id='EVIDENCE-'.substr(sha256_hex("$id\0$status\0$message"),0,16);next if $seen{$evidence_id}++;
    my $g=$groups{$id};$g->{finding_count}++;
    $g->{status}=$status if $g->{status} eq 'NOT_ASSESSED' || $rank{$status}>$rank{$g->{status}};
    $g->{coverage_incomplete}=JSON::PP::true if $message =~ /UNKNOWN|unavailable|unreadable|incomplete=[1-9]|exceeded|timed out|capped files=[1-9]|unparsed|could not/i;
    push @{$data->{findings}},{check_id=>$id,evidence_id=>$evidence_id,status=>$status,section=>$section,check=>$subsection,message=>$message,source=>'text_report'};
}
close $fh;
$data->{checks}=[map {$groups{$_}} sort keys %groups];
my $comparison={status=>'NOT_REQUESTED'};
if (my $previous=$ENV{DEYDA_PREVIOUS_REPORT_JSON}) {
    my $prior;
    my $ok=eval {open my $pf,'<',$previous or die;local $/;my $raw=<$pf>;die if length($raw)>32*1024*1024;$prior=decode_json($raw);close $pf;
        die unless ref($prior) eq 'HASH' && ($prior->{schema}//'') eq 'deyda-ioc-v1' && ($prior->{check_id_scheme}//'') eq 'deyda-group-v1' &&
            ref($prior->{checks}) eq 'ARRAY' && ($prior->{hostname}//'') eq $host;1};
    if (!$ok) {$comparison={status=>'UNKNOWN',reason=>'Previous report unreadable, incompatible IDs, or hostname mismatch. Use a v9.90+ report from this node.'};}
    else {
        my @condition_changes;
        my $pc=$prior->{conditions};my $cc=$data->{conditions};
        if (ref($pc) ne 'HASH' || ($pc->{schema}//'') ne 'deyda-conditions-v1') {push @condition_changes,'previous report has no compatible condition metadata';}
        else {
            for my $key(qw(partition runtime_source baseline_sha256 baseline_source scan_limits config_baseline_sha256)) {
                my ($before,$after)=($pc->{$key}//'UNKNOWN',$cc->{$key}//'UNKNOWN');
                push @condition_changes,"$key differs or is UNKNOWN" if $before ne $after || $before eq 'UNKNOWN' || $after eq 'UNKNOWN';
            }
        }
        my $comparable=!@condition_changes;
        my (%old,%seen_old);my $valid=1;
        for my $g(@{$prior->{checks}}) {
            if (ref($g) ne 'HASH' || ($g->{check_id}//'')!~/^DEYDA-\d{4}$/ || $seen_old{$g->{check_id}}++ || !exists($rank{$g->{status}//''}) && ($g->{status}//'') ne 'NOT_ASSESSED') {$valid=0;last;}
            $old{$g->{check_id}}=$g;
        }
        if (!$valid) {$comparison={status=>'UNKNOWN',reason=>'Previous report contains invalid or duplicate check records.'};}
        else {
            $comparison={status=>'COMPARED',previous_build=>$prior->{build},current_build=>$build,previous_generated_at_epoch=>$prior->{generated_at_epoch},
                conditions_comparable=>$comparable?JSON::PP::true:JSON::PP::false,condition_differences=>\@condition_changes,
                new=>[],improved=>[],worsened=>[],now_ok=>[],not_assessed=>[],coverage_worsened=>[],unchanged=>[]};
            my %ids=map {$_=>1}(keys %old,keys %groups);
            for my $key(sort keys %ids) {
                my($before,$after)=($old{$key},$groups{$key});
                my $row={check_id=>$key,before=>$before?$before->{status}:'NOT_PRESENT',after=>$after?$after->{status}:'NOT_PRESENT'};
                if (!$after || $after->{status} eq 'NOT_ASSESSED') {push @{$comparison->{not_assessed}},$row;next;}
                if (!$before || $before->{status} eq 'NOT_ASSESSED') {push @{$comparison->{new}},$row;next;}
                if ($after->{coverage_incomplete} && !$before->{coverage_incomplete}) {push @{$comparison->{coverage_worsened}},$row;}
                if ($rank{$after->{status}}>$rank{$before->{status}}) {push @{$comparison->{worsened}},$row;}
                elsif ($rank{$after->{status}}<$rank{$before->{status}}) {
                    push @{$comparison->{improved}},$row;
                    push @{$comparison->{now_ok}},$row if $comparable && $after->{status} eq 'OK' && !$after->{coverage_incomplete};
                } else {push @{$comparison->{unchanged}},$row;}
            }
            $comparison->{scope}='Group-level comparison; now_ok means selected check results are OK, not proof of remediation or absence of compromise. Improved/worsened lists are candidate status changes; now_ok is suppressed when conditions differ or are unknown. Partition label is an operator assertion.';
        }
    }
}
$data->{comparison}=$comparison;
open my $out,'>',$json or exit 1;
print $out JSON::PP->new->canonical->pretty->encode($data);close $out or exit 1;
# Append comparison after export, so derived findings cannot contaminate scanned IDs.
if (($comparison->{status}//'') ne 'NOT_REQUESTED') {
    open my $rf,'>>',$report or exit 1;
    print $rf "\n===== Comparison with previous JSON report =====\n";
    if ($comparison->{status} eq 'COMPARED') {
        print $rf "Comparable conditions: ".($comparison->{conditions_comparable}?'YES':'NO / UNKNOWN')."\n";
        print $rf "[CHECK] ".join('; ',@{$comparison->{condition_differences}})."\n" unless $comparison->{conditions_comparable};

        for my $key(qw(new improved worsened now_ok not_assessed coverage_worsened unchanged)) {
            print $rf "$key: ".scalar(@{$comparison->{$key}})."\n";
            my $printed=0;
            for my $row(@{$comparison->{$key}}) {
                last if $printed++>=100;
                print $rf "  $row->{check_id}: $row->{before} -> $row->{after}\n";
            }
        }
        print $rf "$comparison->{scope}\n";
    } else {print $rf "[CHECK] Report comparison UNKNOWN: $comparison->{reason}\n";}
    close $rf;
}
DEYDA_JSON_PERL
    JSON_RC=$?
    if [ "$JSON_RC" -eq 0 ]; then
        chmod 600 "$OUT.json" 2>/dev/null
        printf '\nJSON report saved at: %s.json\n' "$OUT"
    else
        printf '\n[CHECK] JSON export failed; plain-text report remains available.\n'
    fi
fi

printf '\nCompleted. Plain-text report saved at: %s\n' "$OUT"
exec 1>&3 2>&4 3>&- 4>&-
if [ -t 1 ]; then
    safe_display "$OUT" | awk '{gsub(/\[OK\]/, "\033[32m[OK]\033[0m"); gsub(/\[ACTION\]/, "\033[31m[ACTION]\033[0m"); gsub(/\[CHECK\]/, "\033[93m[CHECK]\033[0m"); print}'
else
    safe_display "$OUT"
fi
